-- Source artifact only. Run on the admitted ECS against a fresh compact target.
-- The orchestrator holds an independent READ lock on the entire frozen source.
-- Preserve source DATETIME values as recorded; no import clock replaces an unknown source time.
-- Render __SOURCE_SCHEMA__ only after validating the schema identifier.
CREATE TEMPORARY TABLE compact_support_guard(valid INT NOT NULL CHECK(valid=1)) ENGINE=InnoDB;
CREATE TEMPORARY TABLE `compact_support_chat_project`(source_key VARCHAR(512) COLLATE utf8mb4_bin PRIMARY KEY,source_json LONGTEXT NOT NULL,source_sha256 CHAR(64) NOT NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE `compact_support_chat_message`(source_key VARCHAR(512) COLLATE utf8mb4_bin PRIMARY KEY,source_json LONGTEXT NOT NULL,source_sha256 CHAR(64) NOT NULL) ENGINE=InnoDB;
CREATE TEMPORARY TABLE `compact_support_detection_image_fingerprint`(source_key VARCHAR(512) COLLATE utf8mb4_bin PRIMARY KEY,source_json LONGTEXT NOT NULL,source_sha256 CHAR(64) NOT NULL) ENGINE=InnoDB;
SET @support_source_auto=(SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema='__SOURCE_SCHEMA__' AND table_name='chat_project');
SET @support_target_auto=(SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='chat_project');
SET @support_next_auto=GREATEST(COALESCE(@support_source_auto,1),COALESCE(@support_target_auto,1));
SET @support_auto_sql=CONCAT('ALTER TABLE `chat_project` AUTO_INCREMENT=',@support_next_auto);
PREPARE compact_support_auto FROM @support_auto_sql;
EXECUTE compact_support_auto;
DEALLOCATE PREPARE compact_support_auto;
SET @support_source_auto=(SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema='__SOURCE_SCHEMA__' AND table_name='chat_message');
SET @support_target_auto=(SELECT AUTO_INCREMENT FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='chat_message');
SET @support_next_auto=GREATEST(COALESCE(@support_source_auto,1),COALESCE(@support_target_auto,1));
SET @support_auto_sql=CONCAT('ALTER TABLE `chat_message` AUTO_INCREMENT=',@support_next_auto);
PREPARE compact_support_auto FROM @support_auto_sql;
EXECUTE compact_support_auto;
DEALLOCATE PREPARE compact_support_auto;
START TRANSACTION;
COMMIT;
DROP TEMPORARY TABLE `compact_support_chat_project`;
DROP TEMPORARY TABLE `compact_support_chat_message`;
DROP TEMPORARY TABLE `compact_support_detection_image_fingerprint`;
DROP TEMPORARY TABLE compact_support_guard;
